export const indiasFirstsData=[{id:"first-satellite",title:"First Satellite of India",name:"Aryabhata",year:1975,category:"Science & Technology",icon:"🛰️",description:"Launched on April 19, 1975, Aryabhata marked India's entry into space exploration, designed by ISRO and launched via a Soviet Kosmos-3M rocket.",details:"Named after the 5th-century Indian astronomer, the 360 kg satellite conducted experiments in X-ray astronomy, aeronomics, and solar physics."},{id:"first-woman-pm",title:"First Woman Prime Minister",name:"Indira Gandhi",year:1966,category:"Leadership & Governance",icon:"👩‍💼",description:"Sworn in on January 24, 1966, Indira Gandhi became India's first female Prime Minister, leading across four terms.",details:"Remains the only female Prime Minister in Indian history, known for major economic and green revolution reforms."},{id:"first-metro",title:"First Underground Metro Railway",name:"Kolkata Metro (Calcutta Metro)",year:1984,category:"Infrastructure & Transport",icon:"🚇",description:"Began commercial operations on October 24, 1984, running between Esplanade and Bhowanipore (Netaji Bhavan).",details:"Pioneered underground rapid transit in India and became the 17th operational zone of Indian Railways in 2010."},{id:"first-iit",title:"First Indian Institute of Technology",name:"IIT Kharagpur",year:1951,category:"Education & Research",icon:"🎓",description:"Inaugurated on August 18, 1951, at the former Hijli Detention Camp in West Bengal by Education Minister Maulana Abul Kalam Azad.",details:"Created on the recommendations of the Sarkar Committee to establish premier technical education institutes for post-independence development."},{id:"first-high-court",title:"First High Court in India",name:"Calcutta High Court",year:1862,category:"Law & Justice",icon:"⚖️",description:"Established on July 1, 1862, under the High Courts Act 1861, making it the oldest High Court in the country.",details:"Housed in a neo-Gothic architectural landmark in Kolkata modeled after the Cloth Hall in Ypres, Belgium."},{id:"first-nobel-laureate",title:"First Asian & Indian Nobel Laureate",name:"Rabindranath Tagore",year:1913,category:"Arts & Literature",icon:"✒️",description:"Awarded the Nobel Prize in Literature in 1913 for his profoundly sensitive poetry collection 'Gitanjali' (Song Offerings).",details:"First non-European recipient of a Nobel Prize; composed national anthems for both India and Bangladesh."},{id:"first-national-park",title:"First National Park of India",name:"Jim Corbett National Park (Hailey)",year:1936,category:"Wildlife & Nature",icon:"🐅",description:"Established in 1936 in the Himalayan foothills of Uttarakhand as Hailey National Park to protect the Bengal tiger.",details:"Renamed after legendary hunter-turned-conservationist Jim Corbett; launched Project Tiger in 1973."},{id:"first-indian-space",title:"First Indian Citizen in Space",name:"Wing Commander Rakesh Sharma",year:1984,category:"Science & Technology",icon:"👨‍🚀",description:"Flew aboard Soviet spacecraft Soyuz T-11 on April 3, 1984, spending nearly 8 days in orbit on Salyut 7.",details:"Famous for responding 'Saare Jahan Se Achha' when asked by PM Indira Gandhi how India looked from space."},{id:"first-passenger-train",title:"First Commercial Passenger Train",name:"Bombay to Thane Railway",year:1853,category:"Infrastructure & Transport",icon:"🚂",description:"Covered 34 kilometers between Bori Bunder (Bombay) and Thane on April 16, 1853, pulled by three steam engines.",details:"Inaugurated passenger rail travel in Asia, transporting 400 guests across 14 carriages."},{id:"first-president",title:"First President of Independent India",name:"Dr. Rajendra Prasad",year:1950,category:"Leadership & Governance",icon:"🏛️",description:"Took office on January 26, 1950, upon the enactment of the Constitution of India, serving until 1962.",details:"Presided over the Constituent Assembly of India and remains the longest-serving Indian President."}];export const firstsQuiz